# Spawn points derived from map
SPAWN_POINTS = [
    {"x": (r * 3 + 10) % 40, "y": (r * 5 + 10) % 80, "type": "enemy" if r % 3 else "item"}
    for r in range(60)
]

def get_map() -> List[List[int]]:
    return LEVEL_MAP_DATA

def get_collision() -> List[List[int]]:
    return COLLISION_MASK

def get_spawns():
    return SPAWN_POINTS

def map_size():
    return len(LEVEL_MAP_DATA), len(LEVEL_MAP_DATA[0]) if LEVEL_MAP_DATA else (0, 0)
